"""Opt-in, private inference from owned closing charges; no I/O or runtime activation.

For unchanged cash-relevant terms, the public supplier-value formula is affine in
price: V = aP + b. Two distinct positive charges identify F/a and b/a, not the
supplier's actual cost or financing rate. This assumes unchanged supplier economics.
The returned target minimizes predicted buyer cost; supplier acceptance is unproven.
Callers must supply a fingerprint covering their public package and release data.
"""

import hashlib
import json
import math
from dataclasses import dataclass
from datetime import date

from arena_kit.cost import RELATIONSHIP_GOALS, closing_terms, cost_breakdown, must_haves_ok

LABEL = "inferred_observation"
CORE = {"unit_price", "payment_days", "lead_time_days", "volume_per_year", "contract_months", "incoterm"}
OPTIONAL = {"effective_date": None, "index_clause": None, "tooling_eur": 0,
            "ppm_commitment": 0, "chargeback_eur_per_complaint": 0}
BUYER_FIELDS = ("need_per_year", "horizon_years", "current_unit_price", "fallback_unit_price",
                "interest_rate", "reference_payment_days", "need_lead_time_days", "category_goal",
                "fallback_risk_pct", "index_risk_pct", "late_cost_per_day", "cost_per_defect",
                "sustainable_margin_pct", "relationship_eur_per_point", "freight_eur_per_unit",
                "index_paths", "must_haves")
RECORD_KEYS = {"version", "label", "session_id", "supplier_id", "scope", "terms", "relationship_eur"}
RESIDUAL_EUR = 0.02  # component display rounding, not model/economic uncertainty


def _number(value, minimum=0):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and value >= minimum


def _json(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)


def _complete(terms):
    if not isinstance(terms, dict) or not CORE <= terms.keys() or terms.keys() - CORE - OPTIONAL.keys():
        raise ValueError("expected complete public closing terms")
    out = {**OPTIONAL, **terms}
    for key in (CORE | OPTIONAL.keys()) - {"incoterm", "index_clause", "effective_date"}:
        if not _number(out[key]):
            raise ValueError("nonfinite or negative term")
    if out["unit_price"] <= 0 or out["volume_per_year"] <= 0 or not isinstance(out["incoterm"], str):
        raise ValueError("invalid price, volume or freight term")
    if out["effective_date"] is not None:
        date.fromisoformat(out["effective_date"])
    _json(out)
    return out


def _scope(case, supplier_id, terms, standard, data_fingerprint):
    if not isinstance(data_fingerprint, str) or not data_fingerprint.strip():
        raise ValueError("public data fingerprint is required")
    if supplier_id not in case["suppliers"] or not case.get("parts"):
        raise ValueError("supplier/part mismatch")
    b = case["buyer"]
    if (b.get("category_goal") not in RELATIONSHIP_GOALS
            or not _number(b.get("relationship_eur_per_point"), 1e-12)
            or not _number(b.get("sustainable_margin_pct"), 1e-12)):
        raise ValueError("inactive relationship economics")
    obj = {"supplier_id": supplier_id, "parts": sorted(case["parts"]),
           "case_id": case.get("case_id"), "type": case.get("type"),
           "buyer": {k: b.get(k) for k in BUYER_FIELDS}, "fixed_terms": case.get("fixed_terms", {}),
           "negotiable": case["negotiable"], "term_options": case.get("term_options", {}),
           "standard": standard, "data_fingerprint": data_fingerprint,
           "nonprice_terms": {k: v for k, v in terms.items() if k != "unit_price"}}
    return hashlib.sha256(_json(obj).encode()).hexdigest()


def _legal(case, terms, standard):
    if closing_terms(case, terms, standard) != terms or not must_haves_ok(case, terms, standard):
        return False
    for key, value in case.get("fixed_terms", {}).items():
        if terms.get(key) != value:
            return False
    for key in case["negotiable"]:
        options = case.get("term_options", {}).get(key)
        if options and terms.get(key) not in options and terms.get(key) != standard.get(key):
            return False
    return terms["incoterm"] in case["buyer"]["freight_eur_per_unit"]


def extract_observation(case, outcome, *, session_id, standard, data_fingerprint):
    """Allowlist an owned, ended, valid deal. Never copy outcome metadata or scores.

    Ownership is the caller's provenance obligation; a dictionary cannot prove it.
    Only explicitly supplied session identity, complete terms and charge are retained.
    """
    try:
        if (not isinstance(session_id, str) or not session_id.strip()
                or any(outcome.get(k) is not True for k in ("ended", "deal", "must_haves_ok"))):
            return None
        terms = _complete(outcome["terms"])
        charge = outcome["cost_breakdown"]["relationship"]
        if not _number(charge) or not _legal(case, terms, standard):
            return None
        scope = _scope(case, outcome["supplier_id"], terms, standard, data_fingerprint)
        return {"version": 1, "label": LABEL, "session_id": session_id,
                "supplier_id": outcome["supplier_id"], "scope": scope,
                "terms": json.loads(_json(terms)), "relationship_eur": charge}
    except (KeyError, TypeError, ValueError, OverflowError):
        return None


def _soft(gap):
    return 0.0 if gap <= 0 else gap * gap / 10 if gap <= 5 else gap - 2.5


@dataclass(frozen=True)
class RelationshipFit:
    scope: str
    effective_cost: float  # F/a, not the actual full cost
    price_offset: float  # b/a
    session_ids: tuple[str, ...]
    observed_price_range: tuple[float, float]
    label: str = LABEL


def _charge(model, case, terms):
    b = case["buyer"]
    value = terms["unit_price"] + model.price_offset
    if value <= 0:
        return math.inf
    years = min(terms["contract_months"] / 12 if terms["contract_months"] else 1,
                b["horizon_years"])
    gap = b["sustainable_margin_pct"] - 100 + 100 * model.effective_cost / value
    return b["relationship_eur_per_point"] * years * _soft(gap)


def fit(case, supplier_id, terms, standard, observations, *, data_fingerprint):
    """Fit matching records; reject rank deficiency, conflicts and rounding residuals.

    Two points cannot test the affine/stable-economics assumption. Additional positive
    points test residuals; zero charges impose inequalities. Repeats add no fit rank.
    """
    try:
        terms = _complete(closing_terms(case, terms, standard))
        scope = _scope(case, supplier_id, terms, standard, data_fingerprint)
        if not _legal(case, terms, standard):
            return None
        b = case["buyer"]
        years = min(terms["contract_months"] / 12 if terms["contract_months"] else 1, b["horizon_years"])
        scale = b["relationship_eur_per_point"] * years
        if not _number(scale, 1e-12):
            return None
        records, positive, sessions = [], [], {}
        for obs in observations:
            if (set(obs) != RECORD_KEYS or obs["version"] != 1 or obs["label"] != LABEL
                    or obs["supplier_id"] != supplier_id or obs["scope"] != scope):
                return None
            raw = {"ended": True, "deal": True, "must_haves_ok": True,
                   "supplier_id": supplier_id, "terms": obs["terms"],
                   "cost_breakdown": {"relationship": obs["relationship_eur"]}}
            checked = extract_observation(case, raw, session_id=obs["session_id"], standard=standard,
                                          data_fingerprint=data_fingerprint)
            if checked != obs or (obs["session_id"] in sessions and sessions[obs["session_id"]] != obs):
                return None
            sessions[obs["session_id"]] = obs
            records.append(obs)
            if obs["relationship_eur"] > 0:
                z = obs["relationship_eur"] / scale
                gap = math.sqrt(10 * z) if z <= 2.5 else z + 2.5
                ratio = 1 + (gap - b["sustainable_margin_pct"]) / 100
                if ratio <= 0:
                    return None
                positive.append((obs["terms"]["unit_price"], ratio))
        if len(positive) < 2:
            return None
        (low, rl), (high, rh) = min(positive), max(positive)
        denominator = 1 / rh - 1 / rl
        if high - low < 0.01 or denominator <= 1e-10:
            return None
        effective = (high - low) / denominator
        offset = effective / rh - high
        if not _number(effective, 1e-12) or not math.isfinite(offset):
            return None
        model = RelationshipFit(scope, effective, offset, tuple(sorted(sessions)), (low, high))
        if any(abs(_charge(model, case, o["terms"]) - o["relationship_eur"]) > RESIDUAL_EUR for o in records):
            return None
        return model
    except (KeyError, TypeError, ValueError, OverflowError, ZeroDivisionError):
        return None


def calibrated_cost(model, case, supplier_id, terms, standard, *, data_fingerprint):
    """Public kit components plus fitted relationship; None for any scope mismatch."""
    try:
        terms = _complete(closing_terms(case, terms, standard))
        if (_scope(case, supplier_id, terms, standard, data_fingerprint) != model.scope
                or not _legal(case, terms, standard)):
            return None
        value = sum(cost_breakdown(case, terms, standard).values()) + _charge(model, case, terms)
        return value if math.isfinite(value) else None
    except (AttributeError, KeyError, TypeError, ValueError, OverflowError, ZeroDivisionError):
        return None


def target(model, case, supplier_id, terms, standard, *, data_fingerprint):
    """Cent-priced fixed-package target, only within the observed positive-price span.

    Refuse extrapolation: a boundary optimum requires further observations. Returning
    (predicted C, negotiable terms) never asserts that the supplier will accept them.
    """
    def cost(price):
        return calibrated_cost(model, case, supplier_id, {**terms, "unit_price": price}, standard,
                               data_fingerprint=data_fingerprint)

    if model is None or "unit_price" not in case.get("negotiable", []):
        return None
    low, high = model.observed_price_range
    if cost(low) is None or cost(high) is None:
        return None
    lo, hi = low, high
    for _ in range(70):
        m1, m2 = lo + (hi - lo) / 3, hi - (hi - lo) / 3
        if cost(m1) <= cost(m2):
            hi = m2
        else:
            lo = m1
    middle = round((lo + hi) / 2, 2)
    candidates = [round(middle + k / 100, 2) for k in range(-2, 3) if low < middle + k / 100 < high]
    if not candidates:
        return None
    price = min(candidates, key=lambda p: (cost(p), p))
    if price <= low + 0.01 or price >= high - 0.01:
        return None
    complete = closing_terms(case, {**terms, "unit_price": price}, standard)
    return round(cost(price), 2), {key: complete[key] for key in case["negotiable"]}

