    return rm.extract_observation(owned["case"], outcome(owned, price, charge), session_id=session,
                                  standard=owned["standard"], data_fingerprint=owned["data_fingerprint"])


def test_owned_observations_predict_interior_cost_minimum(owned):
    model = fitted(owned)
    assert model.label == "inferred_observation"
    assert model.effective_cost == pytest.approx(371.68856719)
    assert model.price_offset == pytest.approx(0, abs=0.0001)
    assert set(model.session_ids) == {"49fe810f2e30a206", "60a703adb837d395"}
    fp = owned["data_fingerprint"]
    actual = rm.calibrated_cost(model, *args(owned), data_fingerprint=fp)
    assert actual == pytest.approx(2254487.00, abs=0.01)
    cost, terms = rm.target(model, *args(owned), data_fingerprint=fp)
    assert terms["unit_price"] == 361.33
    assert cost == pytest.approx(2248043.59, abs=0.01)
    assert actual - cost == pytest.approx(6443.41, abs=0.01)
    assert set(terms) == set(owned["case"]["negotiable"])
    # Both branches of the public soft function were needed to identify this fit.
    for record in owned["observations"]:
