def memory_cost(case, terms, standard, supplier):
    """Evaluator hook: None means use the unchanged public expected-cost grid."""
    marker = supplier.get("relationship_memory") or {}
    if not marker:
        return None
    resolved = {**supplier.get("standard", {}), **(standard or {})}
    model = memory.fit(case, marker["supplier_id"], terms, resolved, marker["observations"],
                       data_fingerprint=marker["data_fingerprint"])
    return memory.calibrated_cost(model, case, marker["supplier_id"], terms, resolved,
                                  data_fingerprint=marker["data_fingerprint"]) if model else None


class MemoryOpeningAgent(PackageAgent):
    def __init__(self, *, memory_package, memory_records, memory_fingerprint, **kwargs):
        super().__init__(**kwargs)
        self._memory_package = memory_package
        self._memory_records = memory_records
        self._memory_fingerprint = memory_fingerprint
        self._memory_first = set()

    def _target_supplier(self, case, sid, std):
        key = (case["case_id"], sid)
        if key not in self._target_cache:
            self._target_cache[key] = supplier_estimate(case, sid, package=self._memory_package)
        supplier = super()._target_supplier(case, sid, std)
        if supplier and self._memory_records:
            supplier["relationship_memory"] = {
                "supplier_id": sid, "observations": self._memory_records,
                "data_fingerprint": self._memory_fingerprint,
            }
        return supplier

    def decide(self, case, threads):
        self._memory_first = {sid for sid, events in threads.items() if not self._ours(events)}
        try:
            return super().decide(case, threads)
        finally:
            self._memory_first = set()

    def _target_offer(self, case, sid, terms, std, sup, c_alt, expected_c, reason):
        if sid in self._memory_first and self._memory_records:
            resolved = {**sup.get("standard", {}), **std}
            model = memory.fit(case, sid, terms, resolved, self._memory_records,
                               data_fingerprint=self._memory_fingerprint)
            prediction = memory.target(model, case, sid, terms, resolved,
                                       data_fingerprint=self._memory_fingerprint)
            if prediction:
                expected_c, predicted_terms = prediction
                terms = {**terms, "unit_price": predicted_terms["unit_price"]}
                self._log(case, "relationship_memory_opening", sid, terms=terms, expected_c=expected_c,
                          label=memory.LABEL, source_sessions=list(model.session_ids))
        return super()._target_offer(case, sid, terms, std, sup, c_alt, expected_c, reason)


def configured_memory_agent(policy_config, data_dir, observations_path, release_dir=None, trace_dir=None, **kwargs):
    """Lab factory. Fingerprint the actual public package/release before any session.

    Artifact paths may be absolute or relative to this installed source project's root.
    A data mismatch or empty observations disables memory; public targeting remains on.
    """
    policy = PolicyConfig.from_dict(policy_config)
    if not policy.cost_target_types:
        raise ValueError("memory opening screen requires the serial public cost-target policy")
    package = DataPackage(data_dir, release=release_dir)
    base = fingerprint_data(package.root)
    if base is None:
        raise ValueError("public package fingerprint unavailable")
    fingerprint = base
    if package.release:
        release = fingerprint_data(package.release)
        fingerprint = hashlib.sha256(json.dumps([base, release]).encode()).hexdigest()
    path = Path(observations_path).expanduser()
    if not path.is_absolute():
        path = Path(__file__).resolve().parents[2] / path
    artifact = json.loads(path.read_text())
    records = artifact.get("observations", []) if artifact.get("data_fingerprint") == fingerprint else []
    if not isinstance(records, list) or any(not isinstance(r, dict) or set(r) != memory.RECORD_KEYS for r in records):
        raise ValueError("memory artifact must contain only minimal owned observation records")
    if trace_dir is not None:
        from .trace import Tracer

        kwargs["tracer"] = Tracer(Path(trace_dir))
    return MemoryOpeningAgent(policy=policy, memory_package=package, memory_records=records,
                              memory_fingerprint=fingerprint, **kwargs)

